import{_ as i,o as s,c as t,a3 as d}from"./chunks/framework.Cr9EE2ob.js";const v=JSON.parse('{"title":"Sieve Mail Filtering","description":"Yarilo implements server-side mail filtering via the Sieve language (RFC 5228). Scripts are stored per-user and executed on every incoming LMTP delivery.…","frontmatter":{"outline":[2,4],"head":[["meta",{"name":"robots","content":"noindex"}],["link",{"rel":"canonical","href":"https://doc.yarilomail.org/latest/features/sieve.html"}],["meta",{"property":"og:url","content":"https://doc.yarilomail.org/main/features/sieve.html"}],["meta",{"property":"og:title","content":"Sieve Mail Filtering"}],["meta",{"name":"twitter:title","content":"Sieve Mail Filtering"}],["meta",{"property":"og:description","content":"Yarilo implements server-side mail filtering via the Sieve language (RFC 5228). Scripts are stored per-user and executed on every incoming LMTP delivery.…"}],["meta",{"name":"twitter:description","content":"Yarilo implements server-side mail filtering via the Sieve language (RFC 5228). Scripts are stored per-user and executed on every incoming LMTP delivery.…"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@graph\\":[{\\"@type\\":\\"TechArticle\\",\\"@id\\":\\"https://doc.yarilomail.org/main/features/sieve.html#article\\",\\"mainEntityOfPage\\":\\"https://doc.yarilomail.org/main/features/sieve.html\\",\\"headline\\":\\"Sieve Mail Filtering\\",\\"description\\":\\"Yarilo implements server-side mail filtering via the Sieve language (RFC 5228). Scripts are stored per-user and executed on every incoming LMTP delivery.…\\",\\"dateModified\\":\\"2026-10-31T12:43:41.000Z\\",\\"inLanguage\\":\\"en\\",\\"isPartOf\\":{\\"@id\\":\\"https://doc.yarilomail.org/#website\\"},\\"publisher\\":{\\"@id\\":\\"https://yarilomail.org/#organization\\"}},{\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Yarilo documentation\\",\\"item\\":\\"https://doc.yarilomail.org/main/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":2,\\"name\\":\\"Sieve Mail Filtering\\",\\"item\\":\\"https://doc.yarilomail.org/main/features/sieve.html\\"}]}]}"]]},"headers":[],"relativePath":"features/sieve.md","filePath":"features/sieve.md","lastUpdated":1793450621000}'),a={name:"features/sieve.md"};function o(r,e,n,c,l,p){return s(),t("div",null,[...e[0]||(e[0]=[d('<h1 id="sieve-mail-filtering" tabindex="-1">Sieve Mail Filtering <a class="header-anchor" href="#sieve-mail-filtering" aria-label="Permalink to &quot;Sieve Mail Filtering&quot;">​</a></h1><p>Yarilo implements server-side mail filtering via the Sieve language (RFC 5228). Scripts are stored per-user and executed on every incoming LMTP delivery. Script management is available via the ManageSieve protocol (RFC 5804) on port 4190.</p><h2 id="supported-extensions" tabindex="-1">Supported extensions <a class="header-anchor" href="#supported-extensions" aria-label="Permalink to &quot;Supported extensions&quot;">​</a></h2><p><code>fileinto</code>, <code>reject</code>, <code>ereject</code>, <code>vacation</code>, <code>vacation-seconds</code>, <code>imap4flags</code>, <code>copy</code>, <code>envelope</code>, <code>body</code>, <code>date</code>, <code>index</code>, <code>regex</code>, <code>relational</code>, <code>encoded-character</code>, <code>environment</code>, <code>mailbox</code>, <code>special-use</code>, <code>mailboxid</code>, <code>fcc</code>, <code>editheader</code>, <code>variables</code>, <code>include</code>, <code>duplicate</code>, <code>ihave</code>, <code>enotify</code>, <code>subaddress</code>, <code>spamtest</code>, <code>spamtestplus</code>, <code>virustest</code>, <code>foreverypart</code>, <code>mime</code>, <code>extracttext</code>, <code>replace</code>, <code>enclose</code>, <code>mboxmetadata</code>, <code>servermetadata</code>, <code>imapsieve</code>, <code>vnd.<wbr>yarilo.<wbr>debug</code>, <code>vnd.<wbr>yarilo.<wbr>environment</code>, <code>vnd.<wbr>yarilo.<wbr>pipe</code>, <code>vnd.<wbr>yarilo.<wbr>filter</code>, <code>vnd.<wbr>yarilo.<wbr>execute</code>, <code>vnd.<wbr>yarilo.<wbr>report</code></p><p><code>foreverypart</code> / <code>mime</code> / <code>extracttext</code> (RFC 5703) provide per-MIME-part processing: <code>foreverypart { … }</code> walks the parts depth-first (with <code>break [:name]</code>), <code>header</code>/<code>exists :mime</code> inspect the current part&#39;s headers with the <code>:type</code> / <code>:subtype</code> / <code>:contenttype</code> / <code>:param</code> / <code>:anychild</code> selectors, and <code>extracttext [:first N] [MODIFIER] var</code> captures the current part&#39;s UTF-8 text (with the RFC 5229 value modifiers) into a variable. <code>replace [:mime] [:subject s] [:from s] &lt;text&gt;</code> rewrites the current part (or the whole message outside a loop); <code>enclose [:subject s] [:headers list] &lt;text&gt;</code> wraps the message in a multipart/mixed cover plus the original as <code>message/<wbr>rfc822</code>. A rewritten message is delivered in place of the original. Octet-exact preservation of a pre-existing <code>multipart/<wbr>signed</code> part across a <code>replace</code> is a known limitation.</p><p><code>mailboxid</code> (RFC 9042) resolves folders by their stable <code>MAILBOXID</code> (RFC 8474 OBJECTID) rather than by name: <code>fileinto :mailboxid &quot;&lt;id&gt;&quot; &quot;&lt;fallback&gt;&quot;</code> delivers to the folder carrying <code>&lt;id&gt;</code> if it still exists, otherwise to the positional <code>&lt;fallback&gt;</code> mailbox (honouring <code>:create</code>); the <code>mailboxidexists &quot;&lt;id&gt;&quot;.<wbr>.<wbr>.</code> test is true only when every listed id resolves to an accessible folder. Ids survive RENAME, so a script keeps targeting the right folder after the user renames it.</p><p><code>spamtest</code> / <code>spamtestplus</code> / <code>virustest</code> (RFC 5235) are backed by a configured status header (see <code>sieve_<wbr>spamtest_<wbr>status_<wbr>header</code> / <code>sieve_<wbr>virustest_<wbr>status_<wbr>header</code> below); with no header configured the tests report &quot;not scanned&quot;.</p><p><code>imapsieve</code> (RFC 6785) runs Sieve scripts on <strong>IMAP events</strong> - message <code>APPEND</code>, <code>COPY</code>/<code>MOVE</code>, and flag change (<code>STORE</code>) - not just LMTP delivery. A script is bound to a mailbox through the IMAP METADATA annotation <code>/<wbr>shared/<wbr>imapsieve/<wbr>script</code> (<code>SETMETADATA &quot;&lt;mailbox&gt;&quot; (/<wbr>shared/<wbr>imapsieve/<wbr>script &quot;&lt;name&gt;&quot;)</code>), or server-wide under INBOX; the value names a script in <code>imapsieve_<wbr>script_<wbr>dir</code>. Admin <code>imapsieve_<wbr>global_<wbr>before</code> / <code>imapsieve_<wbr>global_<wbr>after</code> scripts wrap the bound one. Bound scripts live in <code>imapsieve_<wbr>script_<wbr>dir</code>; in the Helm chart, set <code>sieve.<wbr>imapsieve_<wbr>scripts</code> (a <code>name: content</code> map) and a ConfigMap is rendered and mounted read-only at <code>imapsieve_<wbr>script_<wbr>dir</code> in the IMAP pods. Scripts require <code>[&quot;imapsieve&quot;, &quot;environment&quot;]</code> and branch on the event via <code>environment &quot;imap.<wbr>cause&quot;</code> (<code>APPEND</code> / <code>COPY</code> / <code>FLAG</code>); the RFC 6785 items <code>imap.<wbr>mailbox</code>, <code>imap.<wbr>email</code>, <code>imap.<wbr>user</code>, <code>imap.<wbr>changedflags</code> and the vendor <code>vnd.<wbr>yarilo.<wbr>mailbox-from</code> / <code>vnd.<wbr>yarilo.<wbr>mailbox-to</code> (COPY source/destination) are also available. Enable it with <code>imapsieve_<wbr>enabled</code>; all three causes - <code>APPEND</code>, <code>COPY</code> and <code>FLAG</code> - are wired.</p><p><code>mboxmetadata</code> / <code>servermetadata</code> (RFC 5490 §4) expose IMAP METADATA (RFC 5464) annotations to scripts: <code>metadata &quot;&lt;mailbox&gt;&quot; &quot;&lt;entry&gt;&quot; &quot;&lt;value&gt;&quot;</code> / <code>metadataexists &quot;&lt;mailbox&gt;&quot; &quot;&lt;entry&gt;&quot;.<wbr>.<wbr>.</code> read per-mailbox annotations, and <code>servermetadata &quot;&lt;entry&gt;&quot; &quot;&lt;value&gt;&quot;</code> / <code>servermetadataexists &quot;&lt;entry&gt;&quot;.<wbr>.<wbr>.</code> read server-scoped ones. Entry names are the wire-format <code>/<wbr>private/<wbr>…</code> or <code>/<wbr>shared/<wbr>…</code> paths; values come from the same dict the IMAP <code>GETMETADATA</code>/<code>SETMETADATA</code> commands use, so a script sees exactly what a client set. Delivery-time lookups are scoped to the recipient&#39;s personal namespace. <code>extlists</code> is <strong>not</strong> advertised yet - its backing data source is not wired.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>Settings live under <code>sieve:</code> and keep the <code>sieve_</code> prefix there, matching the config keys. The chart&#39;s values use the same names under <code>sieve:</code>.</p><h3 id="sieve.sieve_enabled" tabindex="-1"><code>sieve_<wbr>enabled</code> <a class="header-anchor" href="#sieve.sieve_enabled" aria-label="Permalink to &quot;`sieve_enabled` {#sieve.sieve_enabled}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>false</code></dd><dt>Type</dt><dd>boolean</dd><dt>Helm</dt><dd><code>sieve.sieve_enabled</code></dd></dl></div><p>Run Sieve on LMTP delivery.</p><h3 id="sieve.sieve_max_script_size" tabindex="-1"><code>sieve_<wbr>max_<wbr>script_<wbr>size</code> <a class="header-anchor" href="#sieve.sieve_max_script_size" aria-label="Permalink to &quot;`sieve_max_script_size` {#sieve.sieve_max_script_size}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>65536</code></dd><dt>Type</dt><dd>integer, bytes</dd><dt>Also accepted as</dt><dd><code>protocol.managesieve.max_script_size</code></dd><dt>Helm</dt><dd><code>sieve.sieve_max_script_size</code></dd></dl></div><p>Largest compiled script, one limit for delivery and ManageSieve alike. The alias and this key set to different values refuse startup.</p><h3 id="sieve.sieve_max_redirects" tabindex="-1"><code>sieve_<wbr>max_<wbr>redirects</code> <a class="header-anchor" href="#sieve.sieve_max_redirects" aria-label="Permalink to &quot;`sieve_max_redirects` {#sieve.sieve_max_redirects}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>32</code></dd><dt>Type</dt><dd>integer</dd><dt>Helm</dt><dd><code>sieve.sieve_max_redirects</code></dd></dl></div><p><code>redirect</code> actions per message (RFC 5228 §6.2).</p><h3 id="sieve.sieve_max_num_scripts" tabindex="-1"><code>sieve_<wbr>max_<wbr>num_<wbr>scripts</code> <a class="header-anchor" href="#sieve.sieve_max_num_scripts" aria-label="Permalink to &quot;`sieve_max_num_scripts` {#sieve.sieve_max_num_scripts}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>0</code></dd><dt>Type</dt><dd>integer</dd><dt>Helm</dt><dd><code>sieve.sieve_max_num_scripts</code></dd><dt>See also</dt><dd><a href="/main/features/sieve.html#sieve.sieve_max_storage"><code>sieve_max_storage</code></a></dd></dl></div><p>Scripts one user may store. <code>0</code> is unlimited. See <a href="#managesieve">ManageSieve</a>.</p><h3 id="sieve.sieve_max_storage" tabindex="-1"><code>sieve_<wbr>max_<wbr>storage</code> <a class="header-anchor" href="#sieve.sieve_max_storage" aria-label="Permalink to &quot;`sieve_max_storage` {#sieve.sieve_max_storage}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>0</code></dd><dt>Type</dt><dd>integer, bytes</dd><dt>Helm</dt><dd><code>sieve.sieve_max_storage</code></dd><dt>See also</dt><dd><a href="/main/features/sieve.html#sieve.sieve_max_num_scripts"><code>sieve_max_num_scripts</code></a></dd></dl></div><p>Total size of one user&#39;s stored scripts. <code>0</code> is unlimited.</p><h3 id="sieve.sieve_max_actions" tabindex="-1"><code>sieve_<wbr>max_<wbr>actions</code> <a class="header-anchor" href="#sieve.sieve_max_actions" aria-label="Permalink to &quot;`sieve_max_actions` {#sieve.sieve_max_actions}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>32</code></dd><dt>Type</dt><dd>integer</dd><dt>Helm</dt><dd><code>sieve.sieve_max_actions</code></dd></dl></div><p>Actions one script may take in all (<code>fileinto</code>, <code>redirect</code>, <code>keep</code>, …), a guard against runaway scripts. <code>0</code> is unlimited.</p><h3 id="sieve.sieve_global" tabindex="-1"><code>sieve_<wbr>global</code> <a class="header-anchor" href="#sieve.sieve_global" aria-label="Permalink to &quot;`sieve_global` {#sieve.sieve_global}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd>none</dd><dt>Type</dt><dd>string</dd><dt>Helm</dt><dd><code>sieve.sieve_global</code></dd><dt>See also</dt><dd><a href="/main/features/sieve.html#sieve.sieve_global_scripts"><code>sieve_global_scripts</code></a></dd></dl></div><p>Directory of the scripts <code>include :global</code> names, one <code>&lt;name&gt;.<wbr>sieve</code> each. Users cannot write it. Empty: none.</p><h3 id="sieve.sieve_global_scripts" tabindex="-1"><code>sieve_<wbr>global_<wbr>scripts</code> <a class="header-anchor" href="#sieve.sieve_global_scripts" aria-label="Permalink to &quot;`sieve_global_scripts` {#sieve.sieve_global_scripts}&quot;">​</a></h3><div class="setting-card"><dl><dt>Set in</dt><dd>Helm values</dd><dt>Default</dt><dd><code>{}</code></dd><dt>Type</dt><dd>map</dd><dt>See also</dt><dd><a href="/main/features/sieve.html#sieve.sieve_global"><code>sieve_global</code></a></dd></dl></div><p>Global scripts by name. The chart puts them in a ConfigMap mounted at <code>sieve_<wbr>global</code> in the lmtp and imap containers.</p><h3 id="sieve.sieve_vacation_enabled" tabindex="-1"><code>sieve_<wbr>vacation_<wbr>enabled</code> <a class="header-anchor" href="#sieve.sieve_vacation_enabled" aria-label="Permalink to &quot;`sieve_vacation_enabled` {#sieve.sieve_vacation_enabled}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>true</code></dd><dt>Type</dt><dd>boolean</dd><dt>Helm</dt><dd><code>sieve.sieve_vacation_enabled</code></dd></dl></div><p>Permit the <code>vacation</code> extension (RFC 5230).</p><h3 id="sieve.sieve_vacation_min_period" tabindex="-1"><code>sieve_<wbr>vacation_<wbr>min_<wbr>period</code> <a class="header-anchor" href="#sieve.sieve_vacation_min_period" aria-label="Permalink to &quot;`sieve_vacation_min_period` {#sieve.sieve_vacation_min_period}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>86400</code></dd><dt>Type</dt><dd>integer, seconds</dd><dt>Helm</dt><dd><code>sieve.sieve_vacation_min_period</code></dd><dt>See also</dt><dd><a href="/main/features/sieve.html#sieve.sieve_vacation_max_period"><code>sieve_vacation_max_period</code></a> <a href="/main/features/sieve.html#sieve.sieve_vacation_default_period"><code>sieve_vacation_default_period</code></a></dd></dl></div><p>Shortest reply interval; a shorter <code>:days</code> or <code>:seconds</code> is raised to it. <code>0</code> is no minimum.</p><h3 id="sieve.sieve_vacation_max_period" tabindex="-1"><code>sieve_<wbr>vacation_<wbr>max_<wbr>period</code> <a class="header-anchor" href="#sieve.sieve_vacation_max_period" aria-label="Permalink to &quot;`sieve_vacation_max_period` {#sieve.sieve_vacation_max_period}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>5184000</code></dd><dt>Type</dt><dd>integer, seconds</dd><dt>Helm</dt><dd><code>sieve.sieve_vacation_max_period</code></dd><dt>See also</dt><dd><a href="/main/features/sieve.html#sieve.sieve_vacation_min_period"><code>sieve_vacation_min_period</code></a></dd></dl></div><p>Longest reply interval (60 days); a longer one is lowered to it. <code>0</code> is no maximum.</p><h3 id="sieve.sieve_vacation_default_period" tabindex="-1"><code>sieve_<wbr>vacation_<wbr>default_<wbr>period</code> <a class="header-anchor" href="#sieve.sieve_vacation_default_period" aria-label="Permalink to &quot;`sieve_vacation_default_period` {#sieve.sieve_vacation_default_period}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>604800</code></dd><dt>Type</dt><dd>integer, seconds</dd><dt>Helm</dt><dd><code>sieve.sieve_vacation_default_period</code></dd><dt>See also</dt><dd><a href="/main/features/sieve.html#sieve.sieve_vacation_min_period"><code>sieve_vacation_min_period</code></a></dd></dl></div><p>Interval when the script gives none (7 days). It is kept within the minimum too, so <code>0</code> replies to every message only with <code>sieve_<wbr>vacation_<wbr>min_<wbr>period: 0</code>.</p><h3 id="sieve.sieve_vacation_default_subject" tabindex="-1"><code>sieve_<wbr>vacation_<wbr>default_<wbr>subject</code> <a class="header-anchor" href="#sieve.sieve_vacation_default_subject" aria-label="Permalink to &quot;`sieve_vacation_default_subject` {#sieve.sieve_vacation_default_subject}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd>none</dd><dt>Type</dt><dd>string</dd><dt>Helm</dt><dd><code>sieve.sieve_vacation_default_subject</code></dd></dl></div><p>Subject of a reply to a message without one, when the script gives none. Empty is <code>Automated reply</code>.</p><h3 id="sieve.sieve_vacation_default_subject_template" tabindex="-1"><code>sieve_<wbr>vacation_<wbr>default_<wbr>subject_<wbr>template</code> <a class="header-anchor" href="#sieve.sieve_vacation_default_subject_template" aria-label="Permalink to &quot;`sieve_vacation_default_subject_template` {#sieve.sieve_vacation_default_subject_template}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd>none</dd><dt>Type</dt><dd>string</dd><dt>Helm</dt><dd><code>sieve.sieve_vacation_default_subject_template</code></dd></dl></div><p>Subject of a reply when the script gives none, with <code>%{subject}</code> for the message&#39;s subject. Empty is <code>Auto: %{subject}</code>.</p><h3 id="sieve.sieve_vacation_use_original_recipient" tabindex="-1"><code>sieve_<wbr>vacation_<wbr>use_<wbr>original_<wbr>recipient</code> <a class="header-anchor" href="#sieve.sieve_vacation_use_original_recipient" aria-label="Permalink to &quot;`sieve_vacation_use_original_recipient` {#sieve.sieve_vacation_use_original_recipient}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>false</code></dd><dt>Type</dt><dd>boolean</dd><dt>Helm</dt><dd><code>sieve.sieve_vacation_use_original_recipient</code></dd></dl></div><p>Count the LMTP original recipient (ORCPT) as the user&#39;s address. Only a relay that sends ORCPT gives one; see <a href="/main/protocols/lmtp.html#original-recipient-orcpt">LMTP</a>.</p><h3 id="sieve.sieve_vacation_check_recipient" tabindex="-1"><code>sieve_<wbr>vacation_<wbr>check_<wbr>recipient</code> <a class="header-anchor" href="#sieve.sieve_vacation_check_recipient" aria-label="Permalink to &quot;`sieve_vacation_check_recipient` {#sieve.sieve_vacation_check_recipient}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>true</code></dd><dt>Type</dt><dd>boolean</dd><dt>Helm</dt><dd><code>sieve.sieve_vacation_check_recipient</code></dd></dl></div><p>Reply only to a message that names the user in <code>To</code>, <code>Cc</code>, <code>Bcc</code> or <code>Resent-*</code>.</p><h3 id="sieve.sieve_vacation_send_from_recipient" tabindex="-1"><code>sieve_<wbr>vacation_<wbr>send_<wbr>from_<wbr>recipient</code> <a class="header-anchor" href="#sieve.sieve_vacation_send_from_recipient" aria-label="Permalink to &quot;`sieve_vacation_send_from_recipient` {#sieve.sieve_vacation_send_from_recipient}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>false</code></dd><dt>Type</dt><dd>boolean</dd><dt>Helm</dt><dd><code>sieve.sieve_vacation_send_from_recipient</code></dd></dl></div><p>Send the reply with the recipient as envelope sender instead of <code>&lt;&gt;</code>.</p><h3 id="sieve.sieve_vacation_to_header_ignore_envelope" tabindex="-1"><code>sieve_<wbr>vacation_<wbr>to_<wbr>header_<wbr>ignore_<wbr>envelope</code> <a class="header-anchor" href="#sieve.sieve_vacation_to_header_ignore_envelope" aria-label="Permalink to &quot;`sieve_vacation_to_header_ignore_envelope` {#sieve.sieve_vacation_to_header_ignore_envelope}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>false</code></dd><dt>Type</dt><dd>boolean</dd><dt>Helm</dt><dd><code>sieve.sieve_vacation_to_header_ignore_envelope</code></dd></dl></div><p>Address the reply to the first address in <code>Sender</code>, <code>Resent-From</code> or <code>From</code>, even when it is not the envelope sender.</p><h3 id="sieve.sieve_spamtest_status_header" tabindex="-1"><code>sieve_<wbr>spamtest_<wbr>status_<wbr>header</code> <a class="header-anchor" href="#sieve.sieve_spamtest_status_header" aria-label="Permalink to &quot;`sieve_spamtest_status_header` {#sieve.sieve_spamtest_status_header}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd>none</dd><dt>Type</dt><dd>string</dd><dt>Helm</dt><dd><code>sieve.sieve_spamtest_status_header</code></dd><dt>See also</dt><dd><a href="/main/features/sieve.html#sieve.sieve_spamtest_max_value"><code>sieve_spamtest_max_value</code></a></dd></dl></div><p>Header carrying the spam score for <code>spamtest</code> (RFC 5235), such as <code>X-Spam-Score</code>. Empty: the test reports &quot;not scanned&quot;.</p><h3 id="sieve.sieve_spamtest_max_value" tabindex="-1"><code>sieve_<wbr>spamtest_<wbr>max_<wbr>value</code> <a class="header-anchor" href="#sieve.sieve_spamtest_max_value" aria-label="Permalink to &quot;`sieve_spamtest_max_value` {#sieve.sieve_spamtest_max_value}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>10</code></dd><dt>Type</dt><dd>number</dd><dt>Helm</dt><dd><code>sieve.sieve_spamtest_max_value</code></dd><dt>See also</dt><dd><a href="/main/features/sieve.html#sieve.sieve_spamtest_status_header"><code>sieve_spamtest_status_header</code></a></dd></dl></div><p>The raw header value mapped to the top of the 0..10 scale (0..100 with <code>:percent</code>).</p><h3 id="sieve.sieve_virustest_status_header" tabindex="-1"><code>sieve_<wbr>virustest_<wbr>status_<wbr>header</code> <a class="header-anchor" href="#sieve.sieve_virustest_status_header" aria-label="Permalink to &quot;`sieve_virustest_status_header` {#sieve.sieve_virustest_status_header}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd>none</dd><dt>Type</dt><dd>string</dd><dt>Helm</dt><dd><code>sieve.sieve_virustest_status_header</code></dd><dt>See also</dt><dd><a href="/main/features/sieve.html#sieve.sieve_virustest_max_value"><code>sieve_virustest_max_value</code></a></dd></dl></div><p>Header carrying the virus verdict for <code>virustest</code> (RFC 5235). Empty: &quot;not scanned&quot;.</p><h3 id="sieve.sieve_virustest_max_value" tabindex="-1"><code>sieve_<wbr>virustest_<wbr>max_<wbr>value</code> <a class="header-anchor" href="#sieve.sieve_virustest_max_value" aria-label="Permalink to &quot;`sieve_virustest_max_value` {#sieve.sieve_virustest_max_value}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>5</code></dd><dt>Type</dt><dd>number</dd><dt>Helm</dt><dd><code>sieve.sieve_virustest_max_value</code></dd><dt>See also</dt><dd><a href="/main/features/sieve.html#sieve.sieve_virustest_status_header"><code>sieve_virustest_status_header</code></a></dd></dl></div><p>The raw header value mapped to the top of the 0..5 virus scale.</p><h3 id="sieve.sieve_submission_host" tabindex="-1"><code>sieve_<wbr>submission_<wbr>host</code> <a class="header-anchor" href="#sieve.sieve_submission_host" aria-label="Permalink to &quot;`sieve_submission_host` {#sieve.sieve_submission_host}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd>none</dd><dt>Type</dt><dd>string</dd><dt>Helm</dt><dd><code>sieve.sieve_submission_host</code></dd></dl></div><p>The MTA outbound mail goes through (<code>host[:port]</code>, port 25 by default). Empty: <code>redirect</code> and vacation replies are dropped without a word.</p><h3 id="sieve.sieve_submission_ssl" tabindex="-1"><code>sieve_<wbr>submission_<wbr>ssl</code> <a class="header-anchor" href="#sieve.sieve_submission_ssl" aria-label="Permalink to &quot;`sieve_submission_ssl` {#sieve.sieve_submission_ssl}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>no</code></dd><dt>Type</dt><dd>string</dd><dt>Values</dt><dd><code>no</code> <code>smtps</code> <code>starttls</code></dd><dt>Helm</dt><dd><code>sieve.sieve_submission_ssl</code></dd></dl></div><p>Transport security towards that MTA.</p><h3 id="sieve.sieve_submission_timeout" tabindex="-1"><code>sieve_<wbr>submission_<wbr>timeout</code> <a class="header-anchor" href="#sieve.sieve_submission_timeout" aria-label="Permalink to &quot;`sieve_submission_timeout` {#sieve.sieve_submission_timeout}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>30</code></dd><dt>Type</dt><dd>integer, seconds</dd><dt>Helm</dt><dd><code>sieve.sieve_submission_timeout</code></dd></dl></div><p>Connect and command timeout towards that MTA.</p><h3 id="sieve.sieve_submission_auth_secret" tabindex="-1"><code>sieve_<wbr>submission_<wbr>auth_<wbr>secret</code> <a class="header-anchor" href="#sieve.sieve_submission_auth_secret" aria-label="Permalink to &quot;`sieve_submission_auth_secret` {#sieve.sieve_submission_auth_secret}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd>none</dd><dt>Type</dt><dd>string</dd><dt>Helm</dt><dd><code>sieve.sieve_submission_auth_secret</code></dd></dl></div><p>Name of a Kubernetes Secret with <code>user</code> and <code>password</code> keys for SMTP AUTH. Empty relays without authentication.</p><h3 id="sieve.sieve_default_name" tabindex="-1"><code>sieve_<wbr>default_<wbr>name</code> <a class="header-anchor" href="#sieve.sieve_default_name" aria-label="Permalink to &quot;`sieve_default_name` {#sieve.sieve_default_name}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>yarilo</code></dd><dt>Type</dt><dd>string</dd><dt>Helm</dt><dd><code>sieve.sieve_default_name</code></dd></dl></div><p>Name of the per-user default script, seeded as <code>&lt;name&gt;.<wbr>sieve</code> on first delivery.</p><h3 id="sieve.sieve_extensions" tabindex="-1"><code>sieve_<wbr>extensions</code> <a class="header-anchor" href="#sieve.sieve_extensions" aria-label="Permalink to &quot;`sieve_extensions` {#sieve.sieve_extensions}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>[]</code></dd><dt>Type</dt><dd>list</dd><dt>Helm</dt><dd><code>sieve.sieve_extensions</code></dd><dt>See also</dt><dd><a href="/main/features/sieve.html#sieve.sieve_global_extensions"><code>sieve_global_extensions</code></a></dd></dl></div><p>Extensions users may <code>require</code>. Empty allows every extension the engine declares; a non-empty list is enforced at <code>PUTSCRIPT</code> and at delivery.</p><h3 id="sieve.sieve_global_extensions" tabindex="-1"><code>sieve_<wbr>global_<wbr>extensions</code> <a class="header-anchor" href="#sieve.sieve_global_extensions" aria-label="Permalink to &quot;`sieve_global_extensions` {#sieve.sieve_global_extensions}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>[]</code></dd><dt>Type</dt><dd>list</dd><dt>Helm</dt><dd><code>sieve.sieve_global_extensions</code></dd><dt>See also</dt><dd><a href="/main/features/sieve.html#sieve.sieve_extensions"><code>sieve_extensions</code></a></dd></dl></div><p>Extensions only the administrator&#39;s scripts may use, on top of <code>sieve_<wbr>extensions</code>. A user&#39;s script never gets them, even when <code>sieve_<wbr>extensions</code> lists them. See <a href="#whose-script-gets-which-extensions">Whose script gets which extensions</a>.</p><h3 id="sieve.sieve_scripts_driver" tabindex="-1"><code>sieve_<wbr>scripts_<wbr>driver</code> <a class="header-anchor" href="#sieve.sieve_scripts_driver" aria-label="Permalink to &quot;`sieve_scripts_driver` {#sieve.sieve_scripts_driver}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>fs</code></dd><dt>Type</dt><dd>string</dd><dt>Values</dt><dd><code>fs</code> <code>redis</code></dd><dt>Helm</dt><dd><code>sieve.sieve_scripts_driver</code></dd><dt>See also</dt><dd><a href="/main/features/sieve.html#sieve.sieve_scripts_dict"><code>sieve_scripts_dict</code></a></dd></dl></div><p>Where scripts are stored: <code>fs</code> keeps them as files in the user&#39;s home, <code>redis</code> in the dict that <code>sieve_<wbr>scripts_<wbr>dict</code> names.</p><h3 id="sieve.sieve_scripts_dict" tabindex="-1"><code>sieve_<wbr>scripts_<wbr>dict</code> <a class="header-anchor" href="#sieve.sieve_scripts_dict" aria-label="Permalink to &quot;`sieve_scripts_dict` {#sieve.sieve_scripts_dict}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd>none</dd><dt>Type</dt><dd>string</dd><dt>Helm</dt><dd><code>sieve.sieve_scripts_dict</code></dd><dt>See also</dt><dd><a href="/main/features/sieve.html#sieve.sieve_scripts_driver"><code>sieve_scripts_driver</code></a></dd></dl></div><p>Name of the dict in <code>dicts:</code> used with <code>sieve_<wbr>scripts_<wbr>driver: redis</code>. Ignored for <code>fs</code>.</p><h2 id="managesieve" tabindex="-1">ManageSieve <a class="header-anchor" href="#managesieve" aria-label="Permalink to &quot;ManageSieve&quot;">​</a></h2><p><code>protocol.<wbr>managesieve</code> holds the protocol&#39;s own limits; the script size is <code>sieve.<wbr>sieve_<wbr>max_<wbr>script_<wbr>size</code> above.</p><h3 id="protocol.managesieve.max_invalid_commands" tabindex="-1"><code>max_<wbr>invalid_<wbr>commands</code> <a class="header-anchor" href="#protocol.managesieve.max_invalid_commands" aria-label="Permalink to &quot;`max_invalid_commands` {#protocol.managesieve.max_invalid_commands}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>3</code></dd><dt>Type</dt><dd>integer</dd><dt>Helm</dt><dd><code>protocol.managesieve.max_invalid_commands</code></dd></dl></div><p>Unknown commands before authentication after which the server says <code>BYE</code> and closes.</p><h3 id="protocol.managesieve.managesieve_max_line_length" tabindex="-1"><code>managesieve_<wbr>max_<wbr>line_<wbr>length</code> <a class="header-anchor" href="#protocol.managesieve.managesieve_max_line_length" aria-label="Permalink to &quot;`managesieve_max_line_length` {#protocol.managesieve.managesieve_max_line_length}&quot;">​</a></h3><div class="setting-card"><dl><dt>Default</dt><dd><code>65536</code></dd><dt>Type</dt><dd>integer, bytes</dd><dt>Helm</dt><dd><code>protocol.managesieve.managesieve_max_line_length</code></dd></dl></div><p>A command line or a literal, a script&#39;s body aside. A larger literal is refused before it is read with <code>NO &quot;Literal size too large.<wbr>&quot;</code>, and when the client is already sending it (<code>{N+}</code>), with <code>BYE</code> and close. Before authentication the bound is 8192 bytes.</p><p>A script body over <code>sieve_<wbr>max_<wbr>script_<wbr>size</code> gets <code>NO (QUOTA/<wbr>MAXSIZE)</code> before it is read, closing the connection the same way.</p><h3 id="script-limits" tabindex="-1">Script limits <a class="header-anchor" href="#script-limits" aria-label="Permalink to &quot;Script limits&quot;">​</a></h3><p>Three limits apply to a stored script, judged in this order:</p><ul><li><code>sieve_<wbr>max_<wbr>script_<wbr>size</code> bounds its size: <code>NO (QUOTA/<wbr>MAXSIZE) &quot;Script is too large (max N bytes).<wbr>&quot;</code></li><li><code>sieve_<wbr>max_<wbr>num_<wbr>scripts</code> bounds how many scripts a user keeps: <code>NO (QUOTA/<wbr>MAXSCRIPTS) &quot;Script count quota exceeded (max N scripts).<wbr>&quot;</code></li><li><code>sieve_<wbr>max_<wbr>storage</code> bounds the bytes of all the user&#39;s scripts together: <code>NO (QUOTA/<wbr>MAXSTORAGE) &quot;Script storage quota exceeded (max N bytes).<wbr>&quot;</code></li></ul><p><code>PUTSCRIPT</code> of a name the user already has replaces that script: it adds nothing to the count, and only its new size is charged to the storage. A new name past a limit is refused. <code>0</code> lifts any of the three.</p><p>The same limits hold for <a href="/main/protocols/jmap.html#sieve-scripts">JMAP</a>.</p><p><code>HAVESPACE</code> (RFC 5804 §2.5) asks the same question without uploading. Check whether a 2 KiB script fits as <code>vacation</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HAVESPACE &quot;vacation&quot; 2048</span></span></code></pre></div><p>The reply is <code>OK &quot;Putscript would succeed.<wbr>&quot;</code> or the same <code>NO (QUOTA/<wbr>.<wbr>.<wbr>.<wbr>)</code> that <code>PUTSCRIPT</code> would give. A size of <code>0</code> gets <code>NO &quot;Cannot upload empty script.<wbr>&quot;</code>.</p><p>::: note 2.4.3 and earlier had no <code>HAVESPACE</code>, answering it with <code>NO &quot;Unknown command: HAVESPACE&quot;</code>, and refused an oversized script with <code>QUOTA/<wbr>MAXSCRIPTSIZE</code>, a code RFC 5804 does not define. :::</p><p><code>RENAMESCRIPT</code> onto a name the user already has gets <code>NO (ALREADYEXISTS)</code> and changes neither script; the check runs under the same lock as the rename, so a concurrent session cannot slip a script in between.</p><p>A script name is 1 to 256 characters of valid UTF-8 without control characters, <code>/</code>, <code>\\</code>, U+00FF, U+2028 or U+2029, and is neither <code>.</code> nor <code>.<wbr>.</code>. Any command naming a script otherwise gets <code>NO &quot;Invalid script name.<wbr>&quot;</code>.</p><h2 id="testing-for-an-extension-ihave" tabindex="-1">Testing for an extension (<code>ihave</code>) <a class="header-anchor" href="#testing-for-an-extension-ihave" aria-label="Permalink to &quot;Testing for an extension (`ihave`)&quot;">​</a></h2><p><code>ihave</code> (RFC 5463) answers from the script&#39;s set (see below): it is true only for extensions the build supports and the set allows. <code>variables</code> and <code>encoded-character</code> are never reported.</p><div class="language-sieve vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sieve</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">require</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ihave&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;fileinto&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">];</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ihave</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;editheader&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  addheader</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;X-Seen&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;yes&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fileinto</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Archive&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><ul><li>Under a false <code>ihave</code> the block never runs, and the script is still accepted. It may hold commands of extensions this server does not have or allow.</li><li>Under a true <code>ihave</code> the block may use what the test names, held to the script&#39;s set like a <code>require</code>d extension. Only that block may use it.</li><li>Only a bare <code>ihave</code> as the whole test of an <code>if</code> / <code>elsif</code> opens its block. Inside <code>allof</code>, <code>anyof</code> or <code>not</code>, and in the <code>else</code> after <code>not ihave</code>, the test still answers, but the block opens nothing: a command there needs its extension in <code>require</code>, or the script is refused.</li><li><code>require &quot;ihave&quot;</code> opens nothing else: any other command still needs its extension in <code>require</code>. This holds at delivery, in imapsieve, in included scripts, and at ManageSieve <code>PUTSCRIPT</code> / <code>CHECKSCRIPT</code> and JMAP <code>SieveScript/<wbr>set</code> / <code>SieveScript/<wbr>validate</code>.</li></ul><p>Before 2.4.4, with <code>ihave</code> in <code>sieve_<wbr>extensions</code>, <code>require &quot;ihave&quot;</code> let a script use every extension of the build, whatever the list said. Installations whose <code>sieve_<wbr>extensions</code> did not list <code>ihave</code>, the default included, were not affected.</p><h2 id="whose-script-gets-which-extensions" tabindex="-1">Whose script gets which extensions <a class="header-anchor" href="#whose-script-gets-which-extensions" aria-label="Permalink to &quot;Whose script gets which extensions&quot;">​</a></h2><p>Two sets, built from <code>sieve_<wbr>extensions</code> (empty: every supported extension) and <code>sieve_<wbr>global_<wbr>extensions</code>:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Set</th><th style="text-align:left;">Scripts</th><th style="text-align:left;">Extensions</th></tr></thead><tbody><tr><td style="text-align:left;">A user&#39;s</td><td style="text-align:left;">the active script, <code>include :personal</code>, scripts uploaded through ManageSieve (<code>PUTSCRIPT</code>, <code>CHECKSCRIPT</code>) and JMAP (<code>SieveScript/<wbr>set</code>, <code>SieveScript/<wbr>validate</code>)</td><td style="text-align:left;"><code>sieve_<wbr>extensions</code> less <code>sieve_<wbr>global_<wbr>extensions</code></td></tr><tr><td style="text-align:left;">The administrator&#39;s</td><td style="text-align:left;"><code>sieve_<wbr>global_<wbr>before</code> / <code>sieve_<wbr>global_<wbr>after</code>, the <code>imapsieve_<wbr>scripts</code> a mailbox binds and <code>imapsieve_<wbr>global_<wbr>before</code> / <code>imapsieve_<wbr>global_<wbr>after</code>, <code>include :global</code></td><td style="text-align:left;"><code>sieve_<wbr>extensions</code> and <code>sieve_<wbr>global_<wbr>extensions</code></td></tr></tbody></table><ul><li><strong>A user&#39;s script with a global-only extension</strong> is refused at upload. At delivery it is skipped, as for any extension it may not have. Under <code>ihave</code> such an extension is false.</li><li><strong>The SIEVE capability</strong> of ManageSieve, before login and after, and <code>sieveExtensions</code> in JMAP list a user&#39;s set. Global-only extensions are not advertised.</li><li><strong>An include takes its location&#39;s set,</strong> whoever includes it. A <code>:personal</code> script included by a before script still has only the user&#39;s set, <code>ihave</code> included, and a <code>:global</code> script included by a user&#39;s script has the administrator&#39;s.</li><li><strong>Before/after scripts are checked at load.</strong> <code>sieve_<wbr>global_<wbr>before</code> / <code>_<wbr>after</code> and <code>imapsieve_<wbr>global_<wbr>before</code> / <code>_<wbr>after</code> are held to the administrator&#39;s set when they load. One that uses an extension in neither list is logged (<code>global script uses a forbidden extension, skipping</code>) and left out. Before 2.4.4 they were not checked.</li></ul><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">sieve</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  sieve_extensions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">fileinto</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">envelope</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">variables</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  sieve_global_extensions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">vnd.yarilo.pipe</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">editheader</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><h2 id="including-scripts" tabindex="-1">Including scripts <a class="header-anchor" href="#including-scripts" aria-label="Permalink to &quot;Including scripts&quot;">​</a></h2><p><code>include</code> (RFC 6609) runs another of the user&#39;s own scripts at delivery and in imapsieve:</p><div class="language-sieve vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sieve</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">require</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;include&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">include</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> :personal</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;vacation&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><ul><li>The script is read from the same store as the active one (<code>sieve_<wbr>scripts_<wbr>driver</code>). A script given with no location is <code>:personal</code>.</li><li>An included script is held to its location&#39;s set, whoever includes it: a <code>:personal</code> one to the user&#39;s, a <code>:global</code> one to the administrator&#39;s (see below). One that uses a forbidden extension, or does not compile, fails the run.</li><li>A missing script fails the run, unless the include is <code>:optional</code>. <code>:once</code> includes a script at most once per run. A script that includes itself, directly or through others, fails the run.</li><li><code>:global</code> reads <code>&lt;sieve_<wbr>global&gt;/<wbr>&lt;name&gt;.<wbr>sieve</code>. The name is a script name, never a path. A global script gets the administrator&#39;s set, <code>sieve_<wbr>global_<wbr>extensions</code> included. With <code>sieve_<wbr>global</code> empty, a <code>:global</code> include finds nothing: <code>:optional</code> skips it, a plain one fails the run.</li></ul><p>To ship global scripts with the chart, list them under <code>sieve.<wbr>sieve_<wbr>global_<wbr>scripts</code>. They become a ConfigMap mounted read-only at <code>sieve_<wbr>global</code> in the lmtp and imap containers:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">sieve</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  sieve_global</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/etc/yarilo/sieve-global&quot;</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  sieve_global_scripts</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    spam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      require &quot;fileinto&quot;;</span></span>\n<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      if header :contains &quot;X-Spam-Flag&quot; &quot;YES&quot; { fileinto &quot;Junk&quot;; }</span></span></code></pre></div><p>A user&#39;s script includes one with <code>include :global &quot;spam&quot;;</code>.</p><p>A failed run delivers the message to INBOX (implicit keep) and logs why.</p><h2 id="outbound-mail-from-redirect-and-vacation" tabindex="-1">Outbound mail from redirect and vacation <a class="header-anchor" href="#outbound-mail-from-redirect-and-vacation" aria-label="Permalink to &quot;Outbound mail from redirect and vacation&quot;">​</a></h2><p>When <code>sieve_<wbr>submission_<wbr>host</code> is configured, yarilo dispatches outbound mail for:</p><ul><li><strong><code>redirect</code></strong> - forwards the original message verbatim to the redirect address, preserving the original envelope-from (RFC 5228 §4.2).</li><li><strong><code>vacation</code></strong> - sends an RFC 5230 auto-reply to the original sender with a null envelope-from (<code>&lt;&gt;</code>) to prevent mail loops.</li></ul><h3 id="vacation-replies" tabindex="-1">Vacation replies <a class="header-anchor" href="#vacation-replies" aria-label="Permalink to &quot;Vacation replies&quot;">​</a></h3><p>A reply goes only to mail addressed to the user. The user&#39;s address must be in <code>To</code>, <code>Cc</code>, <code>Bcc</code>, <code>Resent-To</code>, <code>Resent-Cc</code> or <code>Resent-Bcc</code>, as the envelope recipient, as the original recipient (with <code>sieve_<wbr>vacation_<wbr>use_<wbr>original_<wbr>recipient</code>, when the relay gives an ORCPT; see <a href="/main/protocols/lmtp.html#original-recipient-orcpt">LMTP</a>), or as one of the script&#39;s <code>:addresses</code> (RFC 5230 §4.5). Turn <code>sieve_<wbr>vacation_<wbr>check_<wbr>recipient</code> off to reply to any message. A reply is never sent to the user&#39;s own address or to one of <code>:addresses</code> (§4.6).</p><p>The reply:</p><ul><li>comes <code>From</code> the address that matched, unless the script gives <code>:from</code>;</li><li>goes <code>To</code> the sender as named in <code>Sender</code>, <code>Resent-From</code> or <code>From</code>, with the display name, else to the envelope sender;</li><li>has the script&#39;s <code>:subject</code>, else <code>Auto: </code> and the message&#39;s subject (or <code>sieve_<wbr>vacation_<wbr>default_<wbr>subject_<wbr>template</code>), else <code>Automated reply</code> (or <code>sieve_<wbr>vacation_<wbr>default_<wbr>subject</code>) when the message has none;</li><li>carries <code>In-Reply-To</code> and <code>References</code> from the message, so it threads under it (§5.8);</li><li>is <code>text/<wbr>plain; charset=utf-8</code>, unless the script gives <code>:mime</code>, in which case the reason is sent as written, with its own MIME headers;</li><li>has the envelope sender <code>&lt;&gt;</code>, or the recipient with <code>sieve_<wbr>vacation_<wbr>send_<wbr>from_<wbr>recipient</code>.</li></ul><p>A line break in a script&#39;s <code>:subject</code> or <code>:from</code> becomes a space, so a script cannot add headers to the reply.</p><h3 id="vacation-dedup-rfc-5230-§4-5" tabindex="-1">Vacation dedup (RFC 5230 §4.5) <a class="header-anchor" href="#vacation-dedup-rfc-5230-§4-5" aria-label="Permalink to &quot;Vacation dedup (RFC 5230 §4.5)&quot;">​</a></h3><p>Yarilo enforces a per-sender reply interval. It is the action&#39;s <code>:days</code> or <code>:seconds</code>, or <code>sieve_<wbr>vacation_<wbr>default_<wbr>period</code> (7 days) when it gives none, kept between <code>sieve_<wbr>vacation_<wbr>min_<wbr>period</code> (1 day) and <code>sieve_<wbr>vacation_<wbr>max_<wbr>period</code> (60 days). Only an interval that is still <code>0</code> after that, which takes <code>sieve_<wbr>vacation_<wbr>min_<wbr>period: 0</code>, records nothing, so every message is answered. The last-sent timestamp lives where the scripts live, and there is no separate vacation dict:</p><ul><li><code>sieve_<wbr>scripts_<wbr>driver: fs</code> (the default): in <code>.<wbr>yarilo.<wbr>sieve-vacation</code> in the user&#39;s home;</li><li>a dict scripts driver: in that dict under <code>priv/<wbr>sieve/<wbr>vacation/<wbr>&lt;handle&gt;/<wbr>&lt;sender&gt;</code>. Dict drivers with TTL support (Redis) expire the entry automatically; other drivers use the stored timestamp for manual comparison.</li></ul><p>Vacation replies are skipped when:</p><ul><li>The sender address is empty or <code>&lt;&gt;</code>.</li><li>The message has any of <code>List-Id</code>, <code>List-Owner</code>, <code>List-Subscribe</code>, <code>List-Post</code>, <code>List-Unsubscribe</code>, <code>List-Help</code>, <code>List-Archive</code>, or <code>Precedence: bulk/<wbr>list/<wbr>junk</code>.</li><li>The message has an <code>Auto-Submitted:</code> set to any value other than <code>no</code>.</li><li>The message has <code>X-Auto-Response-Suppress:</code> with <code>All</code> or <code>OOF</code>.</li><li>The sender is a system address: <code>MAILER-DAEMON</code>, <code>LISTSERV</code>, <code>majordomo</code>, a local part containing <code>-request</code>, or one starting with <code>owner-</code>.</li></ul><h3 id="duplicate-dedup-rfc-7352" tabindex="-1">Duplicate dedup (RFC 7352) <a class="header-anchor" href="#duplicate-dedup-rfc-7352" aria-label="Permalink to &quot;Duplicate dedup (RFC 7352)&quot;">​</a></h3><p>The <code>duplicate</code> test records tracking IDs with the action&#39;s TTL. The backend is chosen by <strong><code>sieve_<wbr>duplicate_<wbr>driver</code></strong>:</p><ul><li><strong><code>file</code></strong> (default) - a per-user file in the home directory (name: <code>sieve_<wbr>duplicate_<wbr>file</code>, default <code>.<wbr>yarilo.<wbr>sieve-duplicate</code>). The whole check-and-record runs under the per-home Sieve lock, so it is atomic; on shared storage the file is <strong>cross-pod</strong>.</li><li><strong><code>memory</code></strong> - per-process; single-node / dev only.</li><li><strong><code>redis</code></strong> - the dict named <code>sieve_<wbr>duplicate</code> in <code>dicts:</code> (also cross-pod), keyed by <code>priv/<wbr>&lt;user&gt;/<wbr>sieve/<wbr>duplicate/<wbr>&lt;handle&gt;/<wbr>&lt;sha256(id)&gt;</code>.</li></ul><p>Defaults follow RFC 7352: the tracking id is the <code>Message-ID</code> header (absent → the test is false and records nothing); <code>:header</code> / <code>:uniqueid</code> / <code>:handle</code> / <code>:seconds</code> / <code>:last</code> override it. The period defaults to ~7 days and is capped at <code>sieve_<wbr>duplicate_<wbr>max_<wbr>period</code> (default 7 days; a larger <code>:seconds</code> is silently clamped; <code>0</code> = no limit).</p><h3 id="notifications-rfc-5435-enotify" tabindex="-1">Notifications (RFC 5435 <code>enotify</code>) <a class="header-anchor" href="#notifications-rfc-5435-enotify" aria-label="Permalink to &quot;Notifications (RFC 5435 `enotify`)&quot;">​</a></h3><p>The <code>enotify</code> extension (RFC 5435) allows scripts to send notifications via an external method URI. Yarilo supports the <code>mailto:</code> method - the notification is sent as an email via the same <code>sieve_<wbr>submission_<wbr>host</code> as redirect and vacation.</p><div class="language-sieve vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sieve</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">require</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;enotify&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">];</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">notify</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> :message</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;New mail arrived&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;mailto:admin@example.com&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>The <code>mailto:</code> URI may include <code>subject</code> and <code>body</code> query parameters:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mailto:admin@example.com?subject=Alert&amp;body=You+have+mail</span></span></code></pre></div><ul><li><strong>From</strong>: the delivery envelope recipient (your mailbox address).</li><li><strong>Subject</strong>: from the URI <code>subject=</code> parameter; defaults to <code>Notification</code> if absent.</li><li><strong>Body</strong>: <code>ActionNotify.<wbr>Message</code> (<code>:message</code> argument in the script), or URI <code>body=</code> parameter if the script provides no message.</li><li><strong>Envelope-from</strong>: <code>&lt;&gt;</code> (null) to prevent mail loops.</li><li><strong>Auto-Submitted</strong>: <code>auto-generated</code>.</li></ul><p>Methods other than <code>mailto:</code> (e.g. <code>xmpp:</code>, <code>sms:</code>) are logged at <code>WARN</code> level and silently dropped.</p><h3 id="kubernetes-secret-for-smtp-auth" tabindex="-1">Kubernetes secret for SMTP AUTH <a class="header-anchor" href="#kubernetes-secret-for-smtp-auth" aria-label="Permalink to &quot;Kubernetes secret for SMTP AUTH&quot;">​</a></h3><p>Create the secret once:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> secret</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> generic</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sieve-smtp-auth</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --from-literal=user=relay_user</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --from-literal=password=relay_password</span></span></code></pre></div><p>Reference it in <code>values.<wbr>yaml</code>:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">sieve</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  sieve_enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  sieve_submission_host</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;relay.example.com:587&quot;</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  sieve_submission_ssl</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;starttls&quot;</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  sieve_submission_auth_secret</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;sieve-smtp-auth&quot;</span></span></code></pre></div><h2 id="yarilo-specific-extensions" tabindex="-1">Yarilo-specific extensions <a class="header-anchor" href="#yarilo-specific-extensions" aria-label="Permalink to &quot;Yarilo-specific extensions&quot;">​</a></h2><p>Yarilo ships six proprietary Sieve extensions under the <code>vnd.<wbr>yarilo.<wbr>*</code> namespace. They must be listed in the <code>require</code> statement of any script that uses them.</p><hr><h3 id="vnd-yarilo-debug" tabindex="-1"><code>vnd.<wbr>yarilo.<wbr>debug</code> <a class="header-anchor" href="#vnd-yarilo-debug" aria-label="Permalink to &quot;`vnd.yarilo.debug`&quot;">​</a></h3><p>Appends timestamped messages to <code>.<wbr>yarilo.<wbr>sieve.<wbr>log</code> in the user&#39;s home directory. Intended for troubleshooting script logic without touching system logs.</p><div class="language-sieve vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sieve</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">require</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;vnd.yarilo.debug&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">];</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">debug_log</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;fileinto triggered for </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">${subject}</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>The log file is created on first write with mode <code>0600</code>. Each line is <code>&lt;RFC 3339 UTC timestamp&gt; &lt;message&gt;</code>. No configuration required.</p><hr><h3 id="vnd-yarilo-environment" tabindex="-1"><code>vnd.<wbr>yarilo.<wbr>environment</code> <a class="header-anchor" href="#vnd-yarilo-environment" aria-label="Permalink to &quot;`vnd.yarilo.environment`&quot;">​</a></h3><p>Exposes delivery-time variables to scripts via the standard <code>environment</code> test. Built-in items:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Item name</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;"><code>vnd.<wbr>yarilo.<wbr>username</code></td><td style="text-align:left;">Full login name (<code>user@domain</code>)</td></tr><tr><td style="text-align:left;"><code>vnd.<wbr>yarilo.<wbr>default-mailbox</code></td><td style="text-align:left;">Always <code>INBOX</code></td></tr><tr><td style="text-align:left;"><code>vnd.<wbr>yarilo.<wbr>config.<wbr>&lt;key&gt;</code></td><td style="text-align:left;">Operator-defined string from <code>sieve.<wbr>sieve_<wbr>environment</code></td></tr></tbody></table><div class="language-sieve vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sieve</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">require</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;environment&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">];</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> environment</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> :is</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;vnd.yarilo.username&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;alice@example.com&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    fileinto</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;VIP&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Operator config in <code>yarilo.<wbr>yaml</code>:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">sieve</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  sieve_environment</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    tenant</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;acme&quot;</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    region</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;eu-west-1&quot;</span></span></code></pre></div><p>Exposed as <code>vnd.<wbr>yarilo.<wbr>config.<wbr>tenant</code> and <code>vnd.<wbr>yarilo.<wbr>config.<wbr>region</code>.</p><hr><h3 id="vnd-yarilo-pipe" tabindex="-1"><code>vnd.<wbr>yarilo.<wbr>pipe</code> <a class="header-anchor" href="#vnd-yarilo-pipe" aria-label="Permalink to &quot;`vnd.yarilo.pipe`&quot;">​</a></h3><p>Feeds the full RFC 5322 message to an external program. The program receives no output - exit code determines success. Useful for archiving, indexing, or side-effect triggering.</p><div class="language-sieve vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sieve</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">require</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;vnd.yarilo.pipe&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">];</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pipe</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;archive-mail&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;--folder&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;inbox&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">];</span></span></code></pre></div><p><strong>Program resolution</strong> (tried in order):</p><ol><li>Unix socket <code>&lt;sieve_<wbr>pipe_<wbr>socket_<wbr>dir&gt;/<wbr>&lt;name&gt;</code> - if the path is a socket file, yarilo connects and writes the message; socket output is discarded.</li><li>Executable <code>&lt;sieve_<wbr>pipe_<wbr>bin_<wbr>dir&gt;/<wbr>&lt;name&gt;</code> - launched as a subprocess.</li></ol><p>World-writable executables are refused.</p><p><strong>Environment variables</strong> injected into subprocesses:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Variable</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;"><code>USER</code></td><td style="text-align:left;">Delivery recipient login name</td></tr><tr><td style="text-align:left;"><code>SENDER</code></td><td style="text-align:left;">Envelope sender address</td></tr><tr><td style="text-align:left;"><code>RECIPIENT</code></td><td style="text-align:left;">Envelope recipient address</td></tr><tr><td style="text-align:left;"><code>HOME</code></td><td style="text-align:left;">Process home directory</td></tr><tr><td style="text-align:left;"><code>HOST</code></td><td style="text-align:left;">Hostname</td></tr></tbody></table><p><strong>Configuration</strong> (<code>yarilo.<wbr>yaml</code> / <code>values.<wbr>yaml</code>):</p><h4 id="sieve.sieve_pipe_bin_dir" tabindex="-1"><code>sieve_<wbr>pipe_<wbr>bin_<wbr>dir</code> <a class="header-anchor" href="#sieve.sieve_pipe_bin_dir" aria-label="Permalink to &quot;`sieve_pipe_bin_dir` {#sieve.sieve_pipe_bin_dir}&quot;">​</a></h4><div class="setting-card"><dl><dt>Default</dt><dd><code>/usr/lib/yarilo/sieve-pipe</code></dd><dt>Type</dt><dd>string</dd><dt>Helm</dt><dd><code>sieve.sieve_pipe_bin_dir</code></dd></dl></div><p>Directory of the programs <code>vnd.<wbr>yarilo.<wbr>pipe</code> may run.</p><h4 id="sieve.sieve_pipe_socket_dir" tabindex="-1"><code>sieve_<wbr>pipe_<wbr>socket_<wbr>dir</code> <a class="header-anchor" href="#sieve.sieve_pipe_socket_dir" aria-label="Permalink to &quot;`sieve_pipe_socket_dir` {#sieve.sieve_pipe_socket_dir}&quot;">​</a></h4><div class="setting-card"><dl><dt>Default</dt><dd><code>sieve-pipe</code></dd><dt>Type</dt><dd>string</dd><dt>Helm</dt><dd><code>sieve.sieve_pipe_socket_dir</code></dd></dl></div><p>Directory of the sockets <code>vnd.<wbr>yarilo.<wbr>pipe</code> may use, searched first.</p><h4 id="sieve.sieve_pipe_exec_timeout" tabindex="-1"><code>sieve_<wbr>pipe_<wbr>exec_<wbr>timeout</code> <a class="header-anchor" href="#sieve.sieve_pipe_exec_timeout" aria-label="Permalink to &quot;`sieve_pipe_exec_timeout` {#sieve.sieve_pipe_exec_timeout}&quot;">​</a></h4><div class="setting-card"><dl><dt>Default</dt><dd><code>10</code></dd><dt>Type</dt><dd>integer, seconds</dd><dt>Helm</dt><dd><code>sieve.sieve_pipe_exec_timeout</code></dd></dl></div><p>How long one <code>vnd.<wbr>yarilo.<wbr>pipe</code> program may run.</p><h4 id="sieve.sieve_pipe_input_eol" tabindex="-1"><code>sieve_<wbr>pipe_<wbr>input_<wbr>eol</code> <a class="header-anchor" href="#sieve.sieve_pipe_input_eol" aria-label="Permalink to &quot;`sieve_pipe_input_eol` {#sieve.sieve_pipe_input_eol}&quot;">​</a></h4><div class="setting-card"><dl><dt>Default</dt><dd><code>crlf</code></dd><dt>Type</dt><dd>string</dd><dt>Values</dt><dd><code>crlf</code> <code>lf</code></dd><dt>Helm</dt><dd><code>sieve.sieve_pipe_input_eol</code></dd></dl></div><p>Line endings written to the program&#39;s standard input.</p><hr><h3 id="vnd-yarilo-filter" tabindex="-1"><code>vnd.<wbr>yarilo.<wbr>filter</code> <a class="header-anchor" href="#vnd-yarilo-filter" aria-label="Permalink to &quot;`vnd.yarilo.filter`&quot;">​</a></h3><p>Like <code>pipe</code>, but the program&#39;s stdout replaces the message body. If the program exits non-zero or produces no output, the original message is passed through unchanged.</p><div class="language-sieve vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sieve</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">require</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;vnd.yarilo.filter&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">];</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;add-disclaimer&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [] {</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    fileinto</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Filtered&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>The <code>filter</code> action returns <code>true</code> if the program exited 0 and produced output. The same program resolution and environment variable rules as <code>vnd.<wbr>yarilo.<wbr>pipe</code> apply.</p><p><strong>Configuration</strong> (<code>yarilo.<wbr>yaml</code> / <code>values.<wbr>yaml</code>):</p><h4 id="sieve.sieve_filter_bin_dir" tabindex="-1"><code>sieve_<wbr>filter_<wbr>bin_<wbr>dir</code> <a class="header-anchor" href="#sieve.sieve_filter_bin_dir" aria-label="Permalink to &quot;`sieve_filter_bin_dir` {#sieve.sieve_filter_bin_dir}&quot;">​</a></h4><div class="setting-card"><dl><dt>Default</dt><dd><code>/usr/lib/yarilo/sieve-filter</code></dd><dt>Type</dt><dd>string</dd><dt>Helm</dt><dd><code>sieve.sieve_filter_bin_dir</code></dd></dl></div><p>Directory of the programs <code>vnd.<wbr>yarilo.<wbr>filter</code> may run.</p><h4 id="sieve.sieve_filter_socket_dir" tabindex="-1"><code>sieve_<wbr>filter_<wbr>socket_<wbr>dir</code> <a class="header-anchor" href="#sieve.sieve_filter_socket_dir" aria-label="Permalink to &quot;`sieve_filter_socket_dir` {#sieve.sieve_filter_socket_dir}&quot;">​</a></h4><div class="setting-card"><dl><dt>Default</dt><dd><code>sieve-filter</code></dd><dt>Type</dt><dd>string</dd><dt>Helm</dt><dd><code>sieve.sieve_filter_socket_dir</code></dd></dl></div><p>Directory of the sockets <code>vnd.<wbr>yarilo.<wbr>filter</code> may use, searched first.</p><h4 id="sieve.sieve_filter_exec_timeout" tabindex="-1"><code>sieve_<wbr>filter_<wbr>exec_<wbr>timeout</code> <a class="header-anchor" href="#sieve.sieve_filter_exec_timeout" aria-label="Permalink to &quot;`sieve_filter_exec_timeout` {#sieve.sieve_filter_exec_timeout}&quot;">​</a></h4><div class="setting-card"><dl><dt>Default</dt><dd><code>10</code></dd><dt>Type</dt><dd>integer, seconds</dd><dt>Helm</dt><dd><code>sieve.sieve_filter_exec_timeout</code></dd></dl></div><p>How long one <code>vnd.<wbr>yarilo.<wbr>filter</code> program may run.</p><h4 id="sieve.sieve_filter_input_eol" tabindex="-1"><code>sieve_<wbr>filter_<wbr>input_<wbr>eol</code> <a class="header-anchor" href="#sieve.sieve_filter_input_eol" aria-label="Permalink to &quot;`sieve_filter_input_eol` {#sieve.sieve_filter_input_eol}&quot;">​</a></h4><div class="setting-card"><dl><dt>Default</dt><dd><code>crlf</code></dd><dt>Type</dt><dd>string</dd><dt>Values</dt><dd><code>crlf</code> <code>lf</code></dd><dt>Helm</dt><dd><code>sieve.sieve_filter_input_eol</code></dd></dl></div><p>Line endings written to the program&#39;s standard input.</p><hr><h3 id="vnd-yarilo-execute" tabindex="-1"><code>vnd.<wbr>yarilo.<wbr>execute</code> <a class="header-anchor" href="#vnd-yarilo-execute" aria-label="Permalink to &quot;`vnd.yarilo.execute`&quot;">​</a></h3><p>Runs a program with optional stdin and makes its stdout available to the script. Unlike <code>pipe</code>/<code>filter</code>, the program does not receive the full message unless the script explicitly passes content. Exit code is exposed as a boolean result.</p><div class="language-sieve vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sieve</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">require</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;vnd.yarilo.execute&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;variables&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">];</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> execute</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> :input</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;check&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;quota-check&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [] {</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # exit 0 - quota OK</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">} </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">else</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    reject</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Quota exceeded&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>The <code>execute</code> action returns <code>true</code> on exit 0. For Unix socket targets, non-empty output implies success (sockets have no exit code).</p><p>The same program resolution and environment variable rules as <code>vnd.<wbr>yarilo.<wbr>pipe</code> apply.</p><p><strong>Configuration</strong> (<code>yarilo.<wbr>yaml</code> / <code>values.<wbr>yaml</code>):</p><h4 id="sieve.sieve_execute_bin_dir" tabindex="-1"><code>sieve_<wbr>execute_<wbr>bin_<wbr>dir</code> <a class="header-anchor" href="#sieve.sieve_execute_bin_dir" aria-label="Permalink to &quot;`sieve_execute_bin_dir` {#sieve.sieve_execute_bin_dir}&quot;">​</a></h4><div class="setting-card"><dl><dt>Default</dt><dd><code>/usr/lib/yarilo/sieve-execute</code></dd><dt>Type</dt><dd>string</dd><dt>Helm</dt><dd><code>sieve.sieve_execute_bin_dir</code></dd></dl></div><p>Directory of the programs <code>vnd.<wbr>yarilo.<wbr>execute</code> may run.</p><h4 id="sieve.sieve_execute_socket_dir" tabindex="-1"><code>sieve_<wbr>execute_<wbr>socket_<wbr>dir</code> <a class="header-anchor" href="#sieve.sieve_execute_socket_dir" aria-label="Permalink to &quot;`sieve_execute_socket_dir` {#sieve.sieve_execute_socket_dir}&quot;">​</a></h4><div class="setting-card"><dl><dt>Default</dt><dd><code>sieve-execute</code></dd><dt>Type</dt><dd>string</dd><dt>Helm</dt><dd><code>sieve.sieve_execute_socket_dir</code></dd></dl></div><p>Directory of the sockets <code>vnd.<wbr>yarilo.<wbr>execute</code> may use, searched first.</p><h4 id="sieve.sieve_execute_exec_timeout" tabindex="-1"><code>sieve_<wbr>execute_<wbr>exec_<wbr>timeout</code> <a class="header-anchor" href="#sieve.sieve_execute_exec_timeout" aria-label="Permalink to &quot;`sieve_execute_exec_timeout` {#sieve.sieve_execute_exec_timeout}&quot;">​</a></h4><div class="setting-card"><dl><dt>Default</dt><dd><code>10</code></dd><dt>Type</dt><dd>integer, seconds</dd><dt>Helm</dt><dd><code>sieve.sieve_execute_exec_timeout</code></dd></dl></div><p>How long one <code>vnd.<wbr>yarilo.<wbr>execute</code> program may run.</p><h4 id="sieve.sieve_execute_input_eol" tabindex="-1"><code>sieve_<wbr>execute_<wbr>input_<wbr>eol</code> <a class="header-anchor" href="#sieve.sieve_execute_input_eol" aria-label="Permalink to &quot;`sieve_execute_input_eol` {#sieve.sieve_execute_input_eol}&quot;">​</a></h4><div class="setting-card"><dl><dt>Default</dt><dd><code>crlf</code></dd><dt>Type</dt><dd>string</dd><dt>Values</dt><dd><code>crlf</code> <code>lf</code></dd><dt>Helm</dt><dd><code>sieve.sieve_execute_input_eol</code></dd></dl></div><p>Line endings written to the program&#39;s standard input.</p><h3 id="vnd-yarilo-report" tabindex="-1"><code>vnd.<wbr>yarilo.<wbr>report</code> <a class="header-anchor" href="#vnd-yarilo-report" aria-label="Permalink to &quot;`vnd.yarilo.report`&quot;">​</a></h3><p>Generates an <a href="https://www.rfc-editor.org/rfc/rfc5965" target="_blank" rel="noreferrer nofollow">RFC 5965</a> Abuse Reporting Format (ARF) message about the current message and submits it to a target address (via <code>sieve_<wbr>submission_<wbr>host</code>, the same path as <code>redirect</code>/<code>vacation</code>). The report is a <code>multipart/<wbr>report; report-type=feedback-report</code> with a human-readable part, a <code>message/<wbr>feedback-report</code> machine part, and the reported message (full, or headers-only with <code>:headers_<wbr>only</code>).</p><div class="language-sieve vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sieve</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">require</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;vnd.yarilo.report&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">];</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">report</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;abuse&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;User reported this as spam&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;abuse@example.com&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">report</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> :headers_only</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;not-spam&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;False positive&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;fbl@example.com&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>The <code>feedback-type</code> is an RFC 5965 registry token (<code>abuse</code>, <code>fraud</code>, <code>not-spam</code>, …). <code>report</code> is a side-effect action: it does <strong>not</strong> cancel implicit keep, so the message is still delivered.</p><p><strong>Configuration</strong> (<code>yarilo.<wbr>yaml</code> / <code>values.<wbr>yaml</code>):</p><h4 id="sieve.sieve_report_user_agent" tabindex="-1"><code>sieve_<wbr>report_<wbr>user_<wbr>agent</code> <a class="header-anchor" href="#sieve.sieve_report_user_agent" aria-label="Permalink to &quot;`sieve_report_user_agent` {#sieve.sieve_report_user_agent}&quot;">​</a></h4><div class="setting-card"><dl><dt>Default</dt><dd><code>yarilo</code></dd><dt>Type</dt><dd>string</dd><dt>Helm</dt><dd><code>sieve.sieve_report_user_agent</code></dd></dl></div><p>The <code>User-Agent</code> field written into the <code>message/<wbr>feedback-report</code> part.</p><hr><h2 id="default-script" tabindex="-1">Default script <a class="header-anchor" href="#default-script" aria-label="Permalink to &quot;Default script&quot;">​</a></h2><p>On first delivery for a new user, yarilo seeds a default <code>yarilo.<wbr>sieve</code> script:</p><div class="language-sieve vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sieve</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">keep</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>Operators can replace this via ManageSieve, or by writing the script where <code>sieve_<wbr>scripts_<wbr>driver</code> keeps it: a file in the user&#39;s home (<code>fs</code>, the default) or the dict named by <code>sieve_<wbr>scripts_<wbr>dict</code> (<code>redis</code>).</p>',258)])])}const u=i(a,[["render",o]]);export{v as __pageData,u as default};
